import {blank,sample,validate,analyze,uid,toCsv,escapeHtml as esc} from './engine.js';
const KEY='pilotproof.workspace.v1', $=id=>document.getElementById(id);
let state,storedRaw=null,blocked=false,view='overview',editorMode='',editorId='',toastTimer;
try { storedRaw=localStorage.getItem(KEY);state=storedRaw?validate(JSON.parse(storedRaw)):sample(); } catch { state=blank();blocked=true;$('storage-warning').hidden=false;$('storage-warning').textContent='Your saved workspace could not be read. It has been left untouched. Restore a backup or start a new pilot to continue.'; }
const fmt=(v,d=1)=>v===null||!Number.isFinite(v)?'—':new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(v);
const money=v=>v===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const signed=(v,d=1)=>v===null?'—':(v>0?'+':'')+fmt(v,d);
const today=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);};
const notice=text=>{clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6000);};
function commit(next,{replace=false}={}) {
 validate(next);if(blocked&&!replace)throw Error('Restore a valid backup or start a new pilot first.');
 let current=storedRaw;try{current=localStorage.getItem(KEY);}catch{}
 if(!replace&&current!==storedRaw){try{state=current?validate(JSON.parse(current)):blank();storedRaw=current;render();}catch{blocked=true;$('storage-warning').hidden=false;$('storage-warning').textContent='Another tab saved an unreadable workspace. Export your current view before restoring a backup or starting a new pilot.';}throw Error('The workspace changed in another tab. Reopen the editor before saving.');}
 state=next;blocked=false;try{const nextRaw=JSON.stringify(state);localStorage.setItem(KEY,nextRaw);storedRaw=nextRaw;$('storage-warning').hidden=true;$('save-status').textContent='Saved in this browser';}catch{$('storage-warning').hidden=false;$('storage-warning').textContent='Browser storage is unavailable or full. Your changes are in memory only. Export a backup before leaving.';$('save-status').textContent='Export a backup to save';}
 render();
}
function switchView(next){view=next;for(const n of ['overview','evidence','readout'])$(n+'-view').hidden=n!==next;document.querySelectorAll('.tab').forEach(b=>{const active=b.dataset.view===next;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function verdictText(a){if(!a.n)return 'Start with one matched comparison of the same task. Record working time, rework, and the quality result.';if(!a.enough)return `You have ${a.n} of the ${state.brief.minPairs} comparisons in your pilot plan. Keep the conclusion provisional.`;if(!a.qualityComplete)return 'Time is measured, but some quality checks are missing. Complete both checks before judging the pilot against the plan.';if(a.timeMet&&a.qualityMet)return 'The recorded sample meets your time target and quality guardrail. Review comparability and costs with the buyer before deciding what comes next.';return 'The recorded sample falls short on time, quality, or both. Use the individual comparisons to decide what to change or whether to stop.';}
function render(){const a=analyze(state),b=state.brief;
 $('sample-banner').hidden=!state.sample;$('client-label').textContent=b.client||'YOUR NEXT PILOT';$('pilot-title').textContent=b.name;$('workflow-label').textContent=b.workflow||'Define one workflow and the result you want to measure.';
 $('sample-count').textContent=`${a.n} included / ${a.units} units`;
 $('headline-result').innerHTML=a.n?`<div class="result-hero"><span class="big-number ${a.reduction>=0?'positive':'negative'}">${fmt(Math.abs(a.reduction))}%</span><p>${a.reduction>=0?'less':'more'} time per ${esc(b.unit)}<br><span class="eyebrow">IN THE RECORDED SAMPLE</span></p></div>`:'<div class="result-hero"><span class="big-number">—</span><p>Your first comparison<br>starts the evidence.</p></div>';
 const max=Math.max(a.basePer||0,a.trialPer||0,1);$('time-bars').innerHTML=[['Baseline',a.basePer,''],['Pilot',a.trialPer,'trial']].map(([name,v,c])=>`<div class="bar-line"><span>${name}</span><div class="track"><div class="bar ${c}" style="width:${v===null?0:v/max*100}%"></div></div><strong>${fmt(v)} min</strong></div>`).join('');
 $('time-explanation').textContent=a.n?`${fmt(Math.abs(a.delta))} minutes ${a.delta>=0?'freed':'added'} per ${b.unit}; weighted by unit count.`:'Add the same number of units for both runs.';
 $('decision-content').innerHTML=`<h2>${esc(a.status)}</h2><p>${esc(verdictText(a))}</p><ul><li><span>${a.timeMet?'✓':'○'}</span> ${fmt(b.target)}% time-reduction target</li><li><span>${a.qualityMet?'✓':'○'}</span> Quality pass rate holds or improves</li><li><span>${a.enough?'✓':'○'}</span> ${a.n} / ${b.minPairs} planned comparisons</li></ul>`;
 $('metrics').innerHTML=`<div class="metric"><span class="eyebrow">QUALITY · PAIRED CHECKS</span><div class="metric-value">${a.qualityCount?fmt(a.trialPass/a.qualityCount*100,0)+'%':'—'}</div><p>${a.qualityCount?`${a.trialPass}/${a.qualityCount} pilot runs passed; ${a.basePass}/${a.qualityCount} baseline runs passed.`:'Both quality checks are needed to compare pass rates.'} ${a.n-a.qualityCount} incomplete.</p></div><div class="metric"><span class="eyebrow">REWORK PER UNIT</span><div class="metric-value">${a.units?fmt(a.trialRework/a.units)+' min':'—'}</div><p>Baseline: ${a.units?fmt(a.baselineRework/a.units)+' min':'—'}. Rework is included in total time.</p></div><div class="metric"><span class="eyebrow">EVIDENCE COVERAGE</span><div class="metric-value">${a.n} <span style="font-size:1rem;font-weight:500">pairs</span></div><p>${a.excluded} excluded with reasons. Findings describe this sample only.</p></div>`;
 $('brief-summary').innerHTML=`<dl class="definition"><div><dt>Hypothesis</dt><dd>${esc(b.hypothesis||'Write a specific change you expect to see.')}</dd></div><div><dt>Owner</dt><dd>${esc(b.owner||'Not set')}</dd></div><div><dt>Window</dt><dd>${esc(b.start||'Not set')} → ${esc(b.end||'Not set')}</dd></div><div><dt>Success check</dt><dd>At least ${b.minPairs} matched comparisons, ${fmt(b.target)}% less total time, and no decrease in observed quality pass rate.</dd></div><div><dt>Protocol</dt><dd>${esc(b.notes||'Use comparable work and define the same quality checklist for both runs.')}</dd></div></dl>`;
 $('scenario-summary').innerHTML=`<div class="scenario-number ${a.net!==null&&a.net<0?'negative':''}">${money(a.net)}<span style="font-size:.9rem;font-weight:500;letter-spacing:0"> / month</span></div><p class="subtitle">Estimated usable capacity value after recurring cost</p><div style="margin-top:18px"><div class="scenario-line"><span>Usable time, at ${fmt(state.scenario.realization)}%</span><strong>${fmt(a.usableHours)} h</strong></div><div class="scenario-line"><span>${fmt(state.scenario.monthlyUnits)} ${esc(b.unit)} units / month × ${money(state.scenario.hourlyValue)}/h</span><strong>${money(a.capacityValue)}</strong></div><div class="scenario-line"><span>Recurring cost / setup cost</span><strong>${money(state.scenario.monthlyCost)} / ${money(state.scenario.setupCost)}</strong></div><div class="scenario-line"><span>Modeled setup recovery</span><strong>${a.payback===null?'Not reached':fmt(a.payback)+' months'}</strong></div></div>`;
 renderLedger();$('readout-content').innerHTML=reportBody();switchView(view);
}
function renderLedger(){let rows=state.observations;const f=$('evidence-filter').value;if(f!=='all')rows=rows.filter(o=>o.included===(f==='included'));
 if(!rows.length){$('ledger').innerHTML=`<div class="empty"><h3>${state.observations.length?'No comparisons in this view.':'Turn one real task into evidence.'}</h3><p>${state.observations.length?'Choose a different filter to see the rest of the ledger.':'Record the baseline and pilot runs for the same scope of work. Include rework so the time comparison stays honest.'}</p><button class="dark-button" data-add>Add a comparison +</button></div>`;return;}
 const q=v=>v==='unchecked'?'Not checked':v==='pass'?'Pass':'Fail';
 $('ledger').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Matched comparison</th><th>Baseline / unit</th><th>Pilot / unit</th><th>Time change</th><th>Quality · before / after</th><th>Actions</th></tr></thead><tbody>${rows.map(o=>{const before=(o.baseline+o.baselineRework)/o.units,after=(o.trial+o.trialRework)/o.units,diff=after-before;return `<tr class="${o.included?'':'excluded'}"><td><b>${esc(o.label)}</b><small>${esc(o.date)} · ${o.units} ${esc(state.brief.unit)} units${o.included?'':` · Excluded: ${esc(o.exclusion)}`}</small>${o.note?`<small>${esc(o.note)}</small>`:''}</td><td><strong>${fmt(before)} min</strong><small>${fmt(o.baselineRework/o.units)} min rework</small></td><td><strong>${fmt(after)} min</strong><small>${fmt(o.trialRework/o.units)} min rework</small></td><td class="${diff<=0?'positive':'negative'}">${signed(diff)} min</td><td><span class="status-label ${o.baselineQuality}">${q(o.baselineQuality)}</span> / <span class="status-label ${o.trialQuality}">${q(o.trialQuality)}</span></td><td><div class="row-actions"><button data-edit="${esc(o.id)}" aria-label="Edit ${esc(o.label)}">Edit</button><button class="remove" data-delete="${esc(o.id)}" aria-label="Delete ${esc(o.label)}">Delete</button></div></td></tr>`;}).join('')}</tbody></table></div>`;
}
function reportBody(){const a=analyze(state),b=state.brief,s=state.scenario;
 return `<div class="report-top"><strong>PILOTPROOF / PILOT READOUT</strong><span>${esc(today())}</span></div>${state.sample?'<p class="report-alert"><strong>FICTIONAL DEMONSTRATION DATA.</strong> This report is a sample, not a client result.</p>':''}<p class="eyebrow">${esc(b.client||'Client not specified')} · ${esc(b.owner||'Owner not specified')}</p><h1>${esc(b.name)}</h1><p>${esc(b.workflow||'Workflow not specified.')}</p><h2>${esc(a.status)}</h2><p>${esc(verdictText(a))}</p><div class="report-stats"><div><strong>${a.reduction===null?'—':fmt(a.reduction)+'%'}</strong><span>observed time reduction</span></div><div><strong>${a.qualityDelta===null?'—':signed(a.qualityDelta)+' pp'}</strong><span>quality pass-rate change</span></div><div><strong>${a.n} pairs</strong><span>${a.units} units · ${a.excluded} excluded</span></div></div><h2>What we agreed to test</h2><p>${esc(b.hypothesis||'Hypothesis not specified.')}</p><p>Window: ${esc(b.start||'not set')} to ${esc(b.end||'not set')}. Target: at least ${b.minPairs} matched comparisons, ${fmt(b.target)}% less total time per ${esc(b.unit)}, and no decrease in observed quality pass rate.</p><p>${esc(b.notes||'Comparison protocol not specified.')}</p><h2>What was observed</h2><p>Including working time and rework, baseline time was ${fmt(a.basePer)} minutes per unit and pilot time was ${fmt(a.trialPer)} minutes per unit. ${a.qualityCount} included comparisons have both quality checks completed: ${a.basePass} baseline runs and ${a.trialPass} pilot runs passed. ${a.n-a.qualityCount} included comparisons have an incomplete quality check.</p><h2>Scenario for discussion · USD</h2><p>Assumptions: ${fmt(s.monthlyUnits)} units per month, ${money(s.hourlyValue)} per staff hour, ${fmt(s.realization)}% usable capacity, ${money(s.monthlyCost)} recurring monthly cost, and ${money(s.setupCost)} one-time setup cost.</p><p>Projected usable capacity: ${fmt(a.usableHours)} hours/month. Estimated capacity value: ${money(a.capacityValue)}/month; after recurring cost: ${money(a.net)}/month. Modeled setup recovery: ${a.payback===null?'not reached under these inputs':fmt(a.payback)+' months'}.</p><p class="method-note">Formula: (baseline minutes − pilot minutes) ÷ matched units × monthly units ÷ 60 × usable capacity %. Multiply by hourly value and subtract recurring monthly cost. Setup recovery = one-time setup cost ÷ positive monthly net capacity value. These scenarios are not demonstrated cash savings or revenue.</p><h2>Comparison record</h2>${state.observations.length?`<div class="table-wrap"><table><thead><tr><th>Comparison / units</th><th>Baseline min</th><th>Pilot min</th><th>Quality B / P</th><th>Use / reason</th></tr></thead><tbody>${state.observations.map(o=>`<tr><td>${esc(o.label)} / ${o.units}<small>${esc(o.date)}</small></td><td>${fmt(o.baseline+o.baselineRework)}</td><td>${fmt(o.trial+o.trialRework)}</td><td>${esc(o.baselineQuality)} / ${esc(o.trialQuality)}</td><td>${o.included?'Included':'Excluded: '+esc(o.exclusion)}</td></tr>`).join('')}</tbody></table></div><h2>Observation notes</h2><ul>${state.observations.map(o=>`<li><strong>${esc(o.label)}:</strong> ${esc(o.note||'No note supplied.')}</li>`).join('')}</ul>`:'<p>No comparisons recorded.</p>'}<h2>Interpretation and next step</h2><p>These are user-entered paired comparisons, not a randomized study. Differences in task difficulty, operator experience, ordering, or measurement can affect the result. The time calculation pools total minutes and divides by total matched units; quality pass rates count completed paired runs. Quality results may represent different batch sizes.</p><p>Review the comparison protocol, missing quality checks, exclusions, and scenario assumptions together. A target met in this sample supports a discussion about a larger evaluation; it does not establish causation or guarantee future performance.</p><p class="method-note">Prepared with PilotProof by Tom Verdier. No independent verification, statistical significance, customer endorsement, or agreement to purchase is implied. Workspace records stay in the originating browser until exported.</p>`;
}
const field=(name,label,value,type='text',extra='')=>`<label class="field ${type==='textarea'?'wide':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" maxlength="2000" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`;
const select=(name,label,value,options)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;
function openEditor(mode,id=''){editorMode=mode;editorId=id;$('editor-error').textContent='';let html='';
 if(mode==='brief'){const b=state.brief;$('dialog-title').textContent='Agree on one useful test';html=field('name','Pilot name',b.name,'text','required maxlength="150"')+field('client','Client or organization',b.client,'text','maxlength="150"')+field('owner','Pilot owner',b.owner,'text','maxlength="150"')+field('unit','One unit is a…',b.unit,'text','required maxlength="150"')+field('workflow','Comparable workflow',b.workflow,'textarea')+field('hypothesis','Expected change',b.hypothesis,'textarea')+field('target','Time-reduction target (%)',b.target,'number','required min="0" max="100" step="0.1"')+field('minPairs','Minimum paired comparisons',b.minPairs,'number','required min="1" max="2000" step="1"')+field('start','Pilot start',b.start,'date')+field('end','Pilot end',b.end,'date')+field('notes','Protocol and quality checklist',b.notes,'textarea');}
 if(mode==='scenario'){const s=state.scenario;$('dialog-title').textContent='Make the assumptions visible';html='<p class="field wide">These inputs model the value of staff capacity. They do not turn measured time into proven cash savings. All currency is USD.</p>'+field('monthlyUnits','Units per month',s.monthlyUnits,'number','required min="0" max="10000000" step="1"')+field('hourlyValue','Value per staff hour ($)',s.hourlyValue,'number','required min="0" max="10000" step="0.01"')+field('realization','Usable share of time freed (%)',s.realization,'number','required min="0" max="100" step="1"')+field('monthlyCost','Recurring monthly cost ($)',s.monthlyCost,'number','required min="0" max="10000000" step="0.01"')+field('setupCost','One-time setup cost ($)',s.setupCost,'number','required min="0" max="10000000" step="0.01"');}
 if(mode==='observation'){const o=id?state.observations.find(o=>o.id===id):{label:'',date:today(),units:1,baseline:'',baselineRework:0,trial:'',trialRework:0,baselineQuality:'unchecked',trialQuality:'unchecked',included:true,exclusion:'',note:''};$('dialog-title').textContent=id?'Review a matched comparison':'Record one matched comparison';const opts=[['unchecked','Not checked'],['pass','Pass'],['fail','Fail']];html=field('label','Task / comparison label',o.label,'text','required maxlength="150"')+field('date','Comparison recorded on',o.date,'date','required')+field('units','Same unit count in each run',o.units,'number','required min="1" max="1000000" step="1"')+'<p class="field">Compare the same scope of work. Enter total working minutes for the batch; put additional rework minutes in their own fields.</p><div class="form-section">Baseline run</div>'+field('baseline','Working minutes',o.baseline,'number','required min="0" max="1000000" step="0.01"')+field('baselineRework','Additional rework minutes',o.baselineRework,'number','required min="0" max="1000000" step="0.01"')+select('baselineQuality','Baseline quality check',o.baselineQuality,opts)+'<div class="form-section">Pilot run</div>'+field('trial','Working minutes',o.trial,'number','required min="0" max="1000000" step="0.01"')+field('trialRework','Additional rework minutes',o.trialRework,'number','required min="0" max="1000000" step="0.01"')+select('trialQuality','Pilot quality check',o.trialQuality,opts)+'<div class="form-section">Evidence notes</div>'+select('included','Use in the calculation',String(o.included),[['true','Include'],['false','Exclude with a reason']])+field('exclusion','Reason if excluded',o.exclusion,'text','maxlength="500"')+field('note','Source, reviewer, and comparability notes',o.note,'textarea');}
 $('editor-fields').innerHTML='<div class="form-grid">'+html+'</div>';$('editor').showModal();
}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const slug=()=>state.brief.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'pilotproof';
function startNew(){if(!confirm('Start a new pilot? This replaces the current browser workspace. Export a backup first if you want to keep it.'))return;commit(blank(),{replace:true});view='overview';render();openEditor('brief');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view)switchView(b.dataset.view);if(b.hasAttribute('data-add'))openEditor('observation');if(b.dataset.edit)openEditor('observation',b.dataset.edit);if(b.dataset.delete){const o=state.observations.find(o=>o.id===b.dataset.delete);if(confirm(`Delete “${o.label}”? To keep an audit trail, edit it and choose Exclude instead.`)){const next=structuredClone(state);next.observations=next.observations.filter(x=>x.id!==o.id);commit(next);notice('Comparison deleted.');}}}catch(e){notice(e.message);}});
for(const id of ['edit-brief','edit-brief-bottom'])$(id).onclick=()=>openEditor('brief');$('edit-scenario').onclick=()=>openEditor('scenario');$('add-observation').onclick=()=>openEditor('observation');$('evidence-filter').onchange=renderLedger;$('close-dialog').onclick=$('cancel-dialog').onclick=()=>$('editor').close();$('new-pilot').onclick=$('sample-start').onclick=startNew;
 $('editor-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),next=structuredClone(state),get=k=>String(f.get(k)||'').trim(),number=k=>Number(get(k));if(editorMode==='brief'){for(const k of ['name','client','owner','unit','workflow','hypothesis','start','end','notes'])next.brief[k]=get(k);next.brief.target=number('target');next.brief.minPairs=number('minPairs');}if(editorMode==='scenario'){for(const k of Object.keys(next.scenario))next.scenario[k]=number(k);}if(editorMode==='observation'){const o={id:editorId||uid(),label:get('label'),date:get('date'),units:number('units'),baseline:number('baseline'),baselineRework:number('baselineRework'),trial:number('trial'),trialRework:number('trialRework'),baselineQuality:get('baselineQuality'),trialQuality:get('trialQuality'),included:get('included')==='true',exclusion:get('exclusion'),note:get('note')};const i=next.observations.findIndex(x=>x.id===o.id);if(i<0)next.observations.push(o);else next.observations[i]=o;}commit(next);$('editor').close();notice(state.sample?'Sample updated. Start your own pilot before recording real results.':'Changes saved.');}catch(err){$('editor-error').textContent=err.message;}};
 $('export-backup').onclick=()=>download(slug()+'.pilotproof.json',JSON.stringify(state,null,2),'application/json');$('export-csv').onclick=()=>download(slug()+'.observations.csv','\uFEFF'+toCsv(state),'text/csv;charset=utf-8');$('import-backup').onclick=()=>$('backup-file').click();$('backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Choose a workspace smaller than 5 MB.');const next=validate(JSON.parse(await file.text()));if(confirm(`Restore “${next.brief.name}”? This replaces the current workspace. Export a backup first if needed.`)){commit(next,{replace:true});notice('Workspace restored.');}}catch(err){notice('Import failed: '+err.message);}finally{e.target.value='';}};
 $('load-sample').onclick=()=>{if(confirm('Load the fictional sample? This replaces the current workspace. Export a backup first if needed.')){commit(sample(),{replace:true});notice('Fictional sample loaded.');}};
 $('print-report').onclick=()=>{switchView('readout');window.print();};
 $('download-report').onclick=()=>{const css='body{font:16px/1.65 system-ui,sans-serif;color:#101b37;max-width:960px;margin:40px auto;padding:0 22px}h1{font-size:2.1rem;line-height:1.2}h2{margin:30px 0 10px;font-size:1.25rem}.report-top{display:flex;justify-content:space-between;border-bottom:3px solid #101b37;padding-bottom:18px;color:#57627a;font-size:.85rem}.eyebrow{font-size:.8rem;color:#57627a}.report-alert{background:#edf3d9;padding:15px}.report-stats{display:flex;gap:30px;flex-wrap:wrap;border-block:1px solid #dce1e9;padding:20px 0;margin:20px 0}.report-stats strong{display:block;font-size:1.8rem}.report-stats span{font-size:.85rem;color:#57627a}table{border-collapse:collapse;width:100%;font-size:.8rem}th,td{padding:12px 8px;border-bottom:1px solid #dce1e9;text-align:left;vertical-align:top}td small{display:block;color:#57627a}.method-note{font-size:.85rem;color:#57627a}.table-wrap{overflow-x:auto}p,li,td{overflow-wrap:anywhere}@media print{body{margin:0}h2{break-after:avoid}tr{break-inside:avoid}@page{margin:17mm}}';download(slug()+'.readout.html',`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(state.brief.name)} · PilotProof readout</title><style>${css}</style></head><body>${reportBody()}</body></html>`,'text/html;charset=utf-8');notice('Standalone report downloaded. It contains the current observations and assumptions.');};
 window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=e.newValue?validate(JSON.parse(e.newValue)):blank();state=next;storedRaw=e.newValue;blocked=false;$('editor').close();render();notice('Workspace updated in another tab. Reopen any editor to continue.');}catch{notice('Another tab saved an unreadable workspace. Export your current view before reloading.');}});
render();
